CREATE TYPE "ticket_status" AS ENUM ('open','in_progress','waiting_on_customer','resolved','closed');
CREATE TYPE "ticket_priority" AS ENUM ('low','normal','high','urgent');
CREATE TYPE "message_direction" AS ENUM ('inbound','outbound');
CREATE TYPE "delivery_status" AS ENUM ('queued','sent','failed');
CREATE TABLE "contacts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "email" text NOT NULL, "name" text, "company" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "contacts_email_idx" ON "contacts" ("email");
CREATE TABLE "tickets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "number" text NOT NULL, "subject" text NOT NULL, "status" "ticket_status" NOT NULL DEFAULT 'open', "priority" "ticket_priority" NOT NULL DEFAULT 'normal', "contact_id" uuid REFERENCES "contacts"("id"), "assignee" text, "tags" jsonb NOT NULL DEFAULT '[]', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "last_activity_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "tickets_number_idx" ON "tickets" ("number"); CREATE INDEX "tickets_status_idx" ON "tickets" ("status"); CREATE INDEX "tickets_activity_idx" ON "tickets" ("last_activity_at");
CREATE TABLE "messages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "ticket_id" uuid NOT NULL REFERENCES "tickets"("id") ON DELETE CASCADE, "direction" "message_direction" NOT NULL, "from_email" text NOT NULL, "to_email" text NOT NULL, "subject" text NOT NULL, "body_text" text NOT NULL, "body_html" text, "provider_message_id" text, "in_reply_to" text, "delivery" "delivery_status" NOT NULL DEFAULT 'queued', "received_at" timestamptz NOT NULL DEFAULT now(), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "messages_provider_id_idx" ON "messages" ("provider_message_id"); CREATE INDEX "messages_ticket_idx" ON "messages" ("ticket_id", "created_at");
CREATE TABLE "audit_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "ticket_id" uuid NOT NULL REFERENCES "tickets"("id") ON DELETE CASCADE, "actor" text NOT NULL, "event_type" text NOT NULL, "data" jsonb NOT NULL DEFAULT '{}', "created_at" timestamptz NOT NULL DEFAULT now()); CREATE INDEX "audit_ticket_idx" ON "audit_events" ("ticket_id", "created_at");
CREATE TABLE "inbound_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "provider_message_id" text NOT NULL, "payload" jsonb NOT NULL, "processed" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX "inbound_provider_id_idx" ON "inbound_events" ("provider_message_id");
